INSERT INTO `campaigns` VALUES (1,'Raya smoke','Push the Raya bundle for a Malaysian SME.','READY_TO_PUBLISH',NULL,0,0,'2026-08-25 02:11:36','2026-08-25 02:12:43'),(2,'Merdeka 2026','Push patriotics feeling of the product','READY_TO_PUBLISH',NULL,0,0,'2026-08-25 04:11:54','2026-08-25 04:13:59'),(3,'Merdeka Sales','Push the sales to something high','DRAFT',NULL,0,0,'2026-08-26 05:51:08','2026-08-26 05:51:39'),(4,'E2E image check','Sell a Malaysian kopi gift set for Raya to KL office workers.','DRAFT',NULL,0,0,'2026-08-26 05:52:35','2026-08-26 05:52:35'),(5,'E2E image check','Sell a Malaysian kopi gift set for Raya to KL office workers.','DRAFT',NULL,0,0,'2026-08-26 05:55:25','2026-08-26 05:56:56'),(6,'E2E 1','Sell a Malaysian kopi gift set for Raya to KL office workers.','DRAFT',NULL,0,0,'2026-08-26 05:59:33','2026-08-26 06:01:31'),(7,'E2E 2','Sell a Malaysian kopi gift set for Raya to KL office workers.','PENDING_PLAN_APPROVAL',NULL,0,0,'2026-08-26 06:01:31','2026-08-26 06:04:01'),(8,'E2E image 3','Sell a Malaysian kopi gift set for Raya to KL office workers.','DRAFT',NULL,0,0,'2026-08-26 06:02:45','2026-08-26 06:02:45'),(9,'E2E image 4','Sell a Malaysian kopi gift set for Raya to KL office workers.','READY_TO_PUBLISH',NULL,0,0,'2026-08-26 06:05:40','2026-08-26 06:48:49'),(10,'container dim check','Sell a Malaysian kopi gift set for Raya to KL office workers.','PENDING_PLAN_APPROVAL',NULL,0,0,'2026-08-26 07:52:26','2026-08-26 07:54:00'),(11,'Merdeka 2026 Hot Sales','Push the Iphone Sales by introducing the discount in the luxurious way','PENDING_ASSET_REVIEW',NULL,0,1,'2026-08-26 08:35:38','2026-08-26 09:53:51'),(12,'Speed check — Merdeka 2026','Push the iPhone Merdeka sale to young Malaysian professionals. Warm, confident, never hypey.','PENDING_ASSET_REVIEW',NULL,0,0,'2026-08-27 03:09:46','2026-08-27 03:49:00'),(13,'Merdeka Skin Freedom','Campaign focused on selling the Merdeka Barrier Duo (Embun Barrier Cream + Cleanser) for RM79 on Shopee. Targeting Malaysian women 22–35 in urban, humid areas. Positioning the barrier cream as a lightweight \'gel-cream\' that absorbs quickly, aligning with our \'humidity-first\' brand claim. Voice is warm, plainspoken, and honest, avoiding cutesy or clinical tones. Leverages the \'Merdeka\' theme to suggest freedom from heavy skincare routines.','READY_TO_PUBLISH',NULL,0,0,'2026-08-28 07:22:24','2026-08-28 08:18:00'),(14,'Merdeka Luxury Press-On Bundle','Create a campaign that positions the \'Buy 5 Free 5\' offer not just as a discount, but as an invitation to build a personal, luxury-inspired nail collection. Use a polished, fashion-editorial voice reminiscent of high-end beauty houses like Chanel or Dior, focusing on the sensory experience of the at-home manicure ritual. Emphasize the convenience and style of having multiple curated sets for different moods and occasions. Avoid technical claims; focus on the aesthetic and the feeling of elevated self-care. Leverage the trend of \'local pride\' subtly by framing this as accessible luxury for the modern Malaysian woman celebrating her independence and style.','READY_TO_PUBLISH',NULL,0,0,'2026-08-28 08:47:57','2026-08-28 09:28:58'),(15,'Merdeka 2026 Promotion Sales','Push 31% discount sales on 5 items above, target to young audience with luxurious vibe','PENDING_ASSET_REVIEW',NULL,0,0,'2026-08-28 09:40:43','2026-08-28 09:58:02'),(16,'Merdeka Luxury Sale','Launch a patriotic yet luxurious ad campaign for the Merdeka sale, offering a 31% discount on purchases of 5 or more NailIt Signature Press-On Sets. Target luxury-minded women aged 18-35 who value curated aesthetics and at-home beauty rituals. The creative direction must blend national pride with high-end fashion editorial vibes, positioning the press-on nails as an elevated form of self-expression and occasion styling. Avoid medical or durability claims; focus on the polished look and the ritual of application.','READY_TO_PUBLISH',NULL,0,0,'2026-08-28 14:17:17','2026-08-28 14:46:05');
