INSERT INTO `demo_videos` VALUES (1,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/0646d5c87a3d4fd6ba8a0f9bdfae6c20.mp4','/media/4692ec1a25c64750a82feecc47a88d18.png',18,6,'passed',NULL,'pending','2026-08-25 06:32:22','2026-08-25 06:32:22'),(2,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/3052ef9dc2c442b7a17627c7084dab4d.mp4','/media/aeb018aa31af44528414365adf94ae6f.png',18,6,'passed',NULL,'pending','2026-08-25 06:36:38','2026-08-25 06:36:38'),(3,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/d278928e0dd74f53a074b71866aa0732.mp4','/media/1ea03d7710e848f7bbf3edc67086e78a.png',18,6,'passed',NULL,'pending','2026-08-26 10:18:25','2026-08-26 10:18:25'),(4,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/14a9f5bc7e89483989a4025306e21223.mp4','/media/bb677a460a4c428db584b0fbbe7c93fd.png',18,6,'passed',NULL,'pending','2026-08-26 10:47:25','2026-08-26 10:47:25'),(5,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/75fbc148290c4171bf58bd15701cd129.mp4','/media/6267e0821f5f4cf3ae99efe4aba02299.png',18,6,'flagged','The image is a plain gradient background with no product walkthrough, software UI, or visual elements as specified in the layout brief.','pending','2026-08-27 01:55:58','2026-08-27 01:55:58'),(6,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/189d7bcfd1b7482dbf189b2669d2d3f2.mp4','/media/4d47f683ccbb4431a2873a6d46a2b7b0.png',18,6,'flagged','The composited headline \'Build your next campaign with Agentcy.\' does not match the provided headline \'Marketing should move at the speed of your ideas.\'','pending','2026-08-27 01:59:27','2026-08-27 01:59:27'),(7,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/f1a1c361f64e42f29c9a0127d61d127a.mp4','/media/cd1fd811d1ae42c18c29bdf1b8ee7382.png',18,6,'passed',NULL,'pending','2026-08-27 02:05:28','2026-08-27 02:05:28'),(8,'Marketing should move at the speed of your ideas.','Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.','Build your next campaign with Agentcy.','/media/3bbfe46901bb4dd2884f6aeab5c1274d.mp4','/media/db012989b5dc4a7db3e2322565bff6ab.png',18,6,'passed',NULL,'pending','2026-08-27 02:17:41','2026-08-27 02:17:41');
