INSERT INTO `marketing_videos` VALUES (1,'Rumah Blend launch','product_marketing','Kawan Kopi','Rumah Blend','Kuala Lumpur home coffee brewers','Try Rumah Blend','[{\"body\": \"Freshly roasted for the daily cup.\", \"layout\": \"hero\", \"eyebrow\": \"Meet the blend\", \"headline\": \"Coffee that starts at home\"}, {\"body\": \"Chocolatey, balanced and approachable.\", \"layout\": \"feature\", \"eyebrow\": \"What makes it different\", \"headline\": \"Built for how you brew\"}, {\"body\": \"Start with the blend made for your routine.\", \"layout\": \"cta\", \"eyebrow\": \"Your next cup\", \"headline\": \"Bring better coffee home\"}]','/media/e06fbed82141438c974ccebd914efec2.mp4','/media/3ec30e577eda4b2ca28aef3b1bf63f25.png',9,3,'passed',NULL,'pending','2026-08-25 07:04:51','2026-08-25 07:04:51',NULL,0,NULL),(2,'Agentcy software explainer','software_demo','Agentcy','AI marketing campaign workspace','Marketing teams who need a grounded, reviewable campaign workflow.','Build your next campaign with Agentcy.','[{\"body\": \"Agentcy turns your brand truth and a clear brief into a reviewable marketing campaign.\", \"layout\": \"hero\", \"eyebrow\": \"Your marketing team, on demand\", \"headline\": \"Marketing should move at the speed of your ideas.\"}, {\"body\": \"Your company, products, claims and guardrails ground every agent before work begins.\", \"layout\": \"feature\", \"eyebrow\": \"Start with what is true\", \"headline\": \"Set your brand profile.\"}, {\"body\": \"The planner, copywriter, visual planner and director move the campaign forward together.\", \"layout\": \"workflow\", \"eyebrow\": \"One connected workflow\", \"headline\": \"Brief it. Make it. Review it.\"}, {\"body\": \"Vision QA checks the creative first. Your team decides what is approved, redone or rejected.\", \"layout\": \"proof\", \"eyebrow\": \"Keep the decision\", \"headline\": \"Review before anything leaves.\"}, {\"body\": \"Grounded strategy, reviewable creative and a workflow your team can 